const order = $('Get Orders').first().json;
const items = $('Get Order Items').all().map(i => i.json).filter(i => i.id);
const menu = $('Get Menu Items').all().map(m => m.json);

// No Pickup/Delivery saved yet: refuse, so the assistant cannot invent one
if (!order.fulfillment_type) {
  return [{ json: {
    error: 'Pickup or Delivery is NOT saved for this order, so there is no summary yet. Do NOT write a summary. If the customer\'s latest message chose Pickup or Delivery, call Set Delivery Address now and then call Get Order Summary again. Otherwise ask exactly: Would you like Delivery (Rs. 100 fee) or Pickup?',
    fulfillment_type: 'NOT SET'
  }}];
}
if (!items.length) {
  return [{ json: { error: 'This order has no items yet. Do NOT write a summary. Ask the customer what they would like to order.' } }];
}

// One line per menu item: quantities and prices of repeated rows are added together
const grouped = new Map();
for (const i of items) {
  const g = grouped.get(i.menu_item_id) || { qty: 0, total: 0 };
  g.qty += Number(i.quantity);
  g.total += Number(i.line_total);
  grouped.set(i.menu_item_id, g);
}
const lines = [...grouped.entries()].map(([id, g]) => `${g.qty}x ${menu.find(m => m.id === id)?.name ?? 'Unknown'} — Rs. ${g.total}`);

const subtotal = items.reduce((s, i) => s + Number(i.line_total), 0);
const fee = Number(order.delivery_fee || 0);
const total = subtotal + fee;
const hasLoc = !!(Number(order.delivery_lat) && Number(order.delivery_lng));
const isDelivery = order.fulfillment_type === 'Delivery';
const address = order.delivery_address || (hasLoc ? 'your shared location' : '');

const reply_text = [
  'Here\'s your order 🧾',
  ...lines,
  ...(isDelivery ? [`Delivery to: ${address}`, `Delivery fee: Rs. ${fee}`] : ['Pickup']),
  `Total: Rs. ${total}`,
  '',
  'Reply *YES* to confirm.'
].join('\n');

return [{ json: {
  items_text: lines.join('\n'),
  fulfillment_type: order.fulfillment_type,
  delivery_location_saved: !!(order.delivery_address || hasLoc),
  subtotal, delivery_fee: fee, total,
  reply_text
}}];
